SELECT x.* FROM (SELECT p.id, p.symbol, p.opened_at, p.realized_pnl, s.id AS entry_sig, f.id AS f5m_id, f.generated_at AS f5m_gen, f.decision AS f5m_decision, f.original_decision AS f5m_original, f.final_entry_allowed AS f5m_fea, COALESCE(f.decision IN ('NEUTRAL','WATCH') AND f.original_decision IN ('SELL','STRONG_SELL'), 0) AS hidden_bear_5m, COALESCE(f.decision IN ('BUY','STRONG_BUY') AND f.final_entry_allowed = 0, 0) AS blocked_bull_5m FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.id = p.signal_id LEFT JOIN crypto_ai.trade_signal f ON f.id = (SELECT f2.id FROM crypto_ai.trade_signal f2 WHERE f2.symbol = s.symbol AND f2.interval_code = '5m' AND f2.generated_at <= s.generated_at AND f2.generated_at >= DATE_SUB(s.generated_at, INTERVAL 10 MINUTE) ORDER BY f2.generated_at DESC LIMIT 1) WHERE p.status IN ('CLOSED','STOPPED') AND s.interval_code = '1m') x WHERE x.hidden_bear_5m = 1 OR x.blocked_bull_5m = 1 OR x.id IN (172,182) ORDER BY x.id LIMIT 20;